package com.aig.core.cad
import kotlin.math.*
enum class CadTool{SELECT,LINE,RECT,CIRCLE,ARC,HOLE,CHAMFER,FILLET,TRIM,EXTEND,OFFSET,ARRAY};enum class SnapMode{END,MID,CENTER,INTERSECTION,HORIZONTAL,VERTICAL,TANGENT};data class PointMm(val x:Double,val y:Double);sealed interface CadEntity;data class CadLine(val a:PointMm,val b:PointMm):CadEntity;data class CadRect(val a:PointMm,val b:PointMm):CadEntity;data class CadCircle(val center:PointMm,val radius:Double):CadEntity;data class CadHole(val center:PointMm,val radius:Double):CadEntity;data class CadArc(val center:PointMm,val radius:Double,val startDeg:Double,val sweepDeg:Double):CadEntity;data class CadPolyline(val points:List<PointMm>,val closed:Boolean=true):CadEntity;data class CadRoundRect(val a:PointMm,val b:PointMm,val radius:Double):CadEntity;object CadPrecision{const val MM=0.001;fun q(v:Double)=round(v/MM)*MM;fun point(x:Double,y:Double)=PointMm(q(x),q(y))};class CadDocument{var activeTool=CadTool.SELECT;var snapEnabled=true;val snaps=SnapMode.entries.toMutableSet();private val data=mutableListOf<CadEntity>();private val undo=mutableListOf<List<CadEntity>>();private val redo=mutableListOf<List<CadEntity>>();val selected=linkedSetOf<Int>();val entities:List<CadEntity>get()=data;private fun checkpoint(){undo.add(data.toList());if(undo.size>64)undo.removeAt(0);redo.clear()};fun add(e:CadEntity){checkpoint();data.add(e);selected.clear();selected.add(data.lastIndex)};fun undo():Boolean{if(undo.isEmpty())return false;redo.add(data.toList());data.clear();data.addAll(undo.removeAt(undo.lastIndex));selected.clear();return true};fun redo():Boolean{if(redo.isEmpty())return false;undo.add(data.toList());data.clear();data.addAll(redo.removeAt(redo.lastIndex));selected.clear();return true};fun clearSelection(){selected.clear()};fun selectNearest(p:PointMm,t:Double=8.0):Boolean{val i=data.indices.minByOrNull{distance(data[it],p)}?:return false;if(distance(data[i],p)>t)return false;if(!selected.add(i))selected.remove(i);return true};fun snap(p:PointMm,t:Double=4.0):PointMm{if(!snapEnabled)return p;val q=data.flatMap{e->when(e){is CadLine->listOf(e.a,e.b,mid(e.a,e.b));is CadRect->listOf(e.a,e.b,mid(e.a,e.b));is CadCircle->listOf(e.center);is CadHole->listOf(e.center);is CadArc->listOf(e.center);is CadPolyline->e.points;is CadRoundRect->listOf(e.a,e.b,mid(e.a,e.b))}}.minByOrNull{hypot(it.x-p.x,it.y-p.y)}?:return p;return if(hypot(q.x-p.x,q.y-p.y)<=t)q else p};fun trimSelected()=mutate{e->when(e){is CadLine->CadLine(e.a,mid(e.a,e.b));is CadArc->e.copy(sweepDeg=e.sweepDeg/2);else->e}};fun extendSelected()=mutate{e->when(e){is CadLine->CadLine(e.a,PointMm(e.a.x+(e.b.x-e.a.x)*1.25,e.a.y+(e.b.y-e.a.y)*1.25));is CadArc->e.copy(sweepDeg=(e.sweepDeg*1.25).coerceIn(-360.0,360.0));else->e}};fun offsetSelected(d:Double=5.0)=mutate{e->when(e){is CadCircle->e.copy(radius=(e.radius+d).coerceAtLeast(.001));is CadHole->e.copy(radius=(e.radius+d).coerceAtLeast(.001));is CadArc->e.copy(radius=(e.radius+d).coerceAtLeast(.001));is CadRect->CadRect(PointMm(e.a.x-d,e.a.y-d),PointMm(e.b.x+d,e.b.y+d));else->e}};fun arraySelected(dx:Double=20.0,dy:Double=0.0,count:Int=3):Boolean{if(selected.isEmpty())return false;checkpoint();val src=selected.sorted().map{data[it]};selected.clear();repeat(count-1){k->src.forEach{e->data.add(translate(e,dx*(k+1),dy*(k+1)));selected.add(data.lastIndex)}};return true};fun chamferSelected(d:Double=5.0)=mutate{e->if(e !is CadRect)e else{val x0=min(e.a.x,e.b.x);val x1=max(e.a.x,e.b.x);val y0=min(e.a.y,e.b.y);val y1=max(e.a.y,e.b.y);val q=min(d,min(x1-x0,y1-y0)/2);CadPolyline(listOf(PointMm(x0+q,y0),PointMm(x1-q,y0),PointMm(x1,y0+q),PointMm(x1,y1-q),PointMm(x1-q,y1),PointMm(x0+q,y1),PointMm(x0,y1-q),PointMm(x0,y0+q)))}};fun filletSelected(r:Double=5.0)=mutate{e->if(e is CadRect)CadRoundRect(e.a,e.b,r)else e};private fun mutate(f:(CadEntity)->CadEntity):Boolean{if(selected.isEmpty())return false;checkpoint();selected.toList().forEach{i->if(i in data.indices)data[i]=f(data[i])};return true};private fun translate(e:CadEntity,dx:Double,dy:Double):CadEntity{fun p(v:PointMm)=PointMm(v.x+dx,v.y+dy);return when(e){is CadLine->CadLine(p(e.a),p(e.b));is CadRect->CadRect(p(e.a),p(e.b));is CadCircle->e.copy(center=p(e.center));is CadHole->e.copy(center=p(e.center));is CadArc->e.copy(center=p(e.center));is CadPolyline->e.copy(points=e.points.map(::p));is CadRoundRect->e.copy(a=p(e.a),b=p(e.b))}};private fun mid(a:PointMm,b:PointMm)=PointMm((a.x+b.x)/2,(a.y+b.y)/2);private fun distance(e:CadEntity,p:PointMm)=when(e){is CadLine->hypot(p.x-(e.a.x+e.b.x)/2,p.y-(e.a.y+e.b.y)/2);is CadRect->hypot(p.x-(e.a.x+e.b.x)/2,p.y-(e.a.y+e.b.y)/2);is CadCircle->abs(hypot(p.x-e.center.x,p.y-e.center.y)-e.radius);is CadHole->abs(hypot(p.x-e.center.x,p.y-e.center.y)-e.radius);is CadArc->abs(hypot(p.x-e.center.x,p.y-e.center.y)-e.radius);is CadPolyline->e.points.minOfOrNull{hypot(p.x-it.x,p.y-it.y)}?:1e9;is CadRoundRect->hypot(p.x-(e.a.x+e.b.x)/2,p.y-(e.a.y+e.b.y)/2)}}
